select t.password,t.address,t.sex,t.name,t.tel,t.status_cd,t.status_cd statusCd,t.user_id,t.user_id
userId,t.level_cd,t.level_cd levelCd,t.email,t.face_url faceUrl
from u_user t
where 1 =1

    and t.password= #{password}


    and t.address= #{address}


    and t.sex= #{sex}


    and t.name= #{name}


    and t.tel= #{tel}


    and t.status_cd= #{statusCd}


    and t.user_id= #{userId}


    and t.level_cd= #{levelCd}


    and t.level_cd in

        #{item}



    and t.email= #{email}

order by t.create_time desc

    limit #{page}, #{row}

