select DISTINCT t.address,t.sex,t.status_cd,t.status_cd statusCd,t.user_id,t.user_id userId,t.level_cd,t.level_cd levelCd,t.name,t.tel,t.email,t.create_time createTime from u_user t inner join s_store_user su on t.user_id = su.staff_id and su.status_cd = '0' LEFT JOIN u_org_staff_rel osr on su.staff_id = osr.staff_id and osr.status_cd = '0' where t.level_cd = '01' and su.store_id = #{storeId} and (osr.org_id != #{orgId} or osr.org_id is null)
and t.name like concat('%', #{staffName},'%')
and osr.org_id in
#{item}
order by t.create_time desc
limit #{page}, #{row}

select uu.user_id userId, uu.name, uu.email, uu.address, uu.sex, uu.tel, uu.level_cd levelCd from u_user uu left join s_store_staff sss on uu.user_id = sss.staff_id and sss.status_cd = '0' left join s_store ss on sss.store_id = ss.store_id and ss.status_cd = '0' left join s_community_member scm on ss.store_id = scm.member_id and scm.status_cd = '0' left join s_community sc on scm.community_id = sc.community_id and sc.status_cd = '0' where uu.status_cd = '0'
and sc.community_id = #{communityId}
order by uu.create_time desc
